create index if not exists idx_exam_date_slots_date on public.exam_date_slots (exam_date);
create index if not exists idx_exam_date_slots_class on public.exam_date_slots (class_key);

-- ---------------------------------------------------------------------------
-- Previous-year question papers
--
-- uploader_student_id is the student's device identity (GBU-XXXXXX). It is a
-- plain text column on purpose: it must survive the guest flow, where there
-- is no auth user to hang a uuid off. uploader_id is the Supabase Auth id and
-- is only set for a signed-in student.
-- ---------------------------------------------------------------------------
create table if not exists public.pyq_papers (
  id uuid primary key default gen_random_uuid(),
  school text not null,
  programme_code text not null default '',
  semester text not null,
  subject_code text not null,
  subject_name text not null,
  year integer not null,
  exam_type text not null default 'End Sem',
  file_path text not null,
  uploader_id uuid references auth.users (id) on delete set null,
  uploader_student_id text not null default '',
  uploader_name text not null default '',
  uploader_avatar text not null default '',
  file_size_bytes bigint not null default 0,
  status text not null default 'pending',
  downloads integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists pyq_papers_status_idx on public.pyq_papers (status);
create index if not exists pyq_papers_subject_idx
  on public.pyq_papers (programme_code, semester, subject_code, year, exam_type);
-- The school-first browse path (app/(tabs)/pyq.tsx) filters on school before
-- programme, so the composite index has to lead with school.
create index if not exists pyq_papers_browse_idx
  on public.pyq_papers (school, programme_code, semester);
create index if not exists pyq_papers_uploader_idx
  on public.pyq_papers (uploader_student_id);

-- ---------------------------------------------------------------------------
-- Moderation allowlist
--
-- The seed rows live in supabase/seed.sql, which the owner runs ONCE by hand.
-- They are deliberately NOT in this script: pasting this script must never
-- overwrite a live role.
-- ---------------------------------------------------------------------------
create table if not exists public.moderators (
  id uuid primary key default gen_random_uuid(),
  email text not null unique,
  role text not null default 'moderator',
  added_at timestamptz not null default now()
);

-- Records that the admin console has been claimed by a real account, so a
-- second person cannot run "Initial Setup" after the owner has signed in.
create table if not exists public.admin_claims (
  id uuid primary key default gen_random_uuid(),
  email text not null unique,
  claimed_at timestamptz not null default now()
);

-- Moderation trail: every approve / reject / request-changes decision.
create table if not exists public.pyq_moderation_log (
  id uuid primary key default gen_random_uuid(),
  paper_id uuid not null references public.pyq_papers (id) on delete cascade,
  action text not null,
  moderator_email text,
  note text,
  created_at timestamptz not null default now()
);
create index if not exists pyq_moderation_log_paper_idx
  on public.pyq_moderation_log (paper_id, created_at desc);

create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
