-- ---------------------------------------------------------------------------
-- Student reports
--
-- The report body lives in 'reason' (plain text). The identity lives in real
-- columns — never smuggled through a JSON blob in 'reason' — so a moderator
-- can always see who filed a report, and a student can only ever read their
-- own rows.
-- ---------------------------------------------------------------------------
create table if not exists public.reports (
  id uuid primary key default gen_random_uuid(),
  reporter_id uuid references auth.users (id) on delete set null,
  reporter_student_id text not null default '',
  reporter_name text not null default '',
