-- ---------------------------------------------------------------------------
-- Contributor points, derived from approved papers.
--
-- security_invoker makes the view honour the RLS of pyq_papers, so an
-- anonymous caller sees approved rows only — exactly the rows the browse
-- screen shows. Points are server-derived so two devices cannot disagree.
-- ---------------------------------------------------------------------------
create or replace view public.pyq_contributor_points
with (security_invoker = true) as
select
  uploader_student_id,
  count(*) filter (where status = 'approved') as approved_uploads,
  coalesce(sum(downloads), 0) as total_downloads,
  (count(*) filter (where status = 'approved')) * 50
    + coalesce(sum(downloads), 0) as points
from public.pyq_papers
where uploader_student_id is not null and uploader_student_id <> ''
group by uploader_student_id;
grant select on public.pyq_contributor_points to anon, authenticated;

-- ===========================================================================
-- Storage buckets
--
-- pyq-pending : uploads land here and stay PRIVATE until a moderator
--                approves them. 20 MB cap, PDF/JPG/PNG only.
-- pyq          : approved papers, readable by everyone.
-- pyq-files    : documents uploaded by the admin console (date sheets).
-- campus-events: the CDN JSON blobs the app reads (notices/events/version).
--
-- The ON CONFLICT clause used to be 'do update set public = true', which made
-- a re-paste of this script turn the PRIVATE pending bucket public. Each row
-- now carries its own intended visibility.
-- ===========================================================================
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('pyq-pending', 'pyq-pending', false, 20971520, array['application/pdf','image/jpeg','image/png']),
  ('pyq', 'pyq', true, 20971520, array['application/pdf','image/jpeg','image/png']),
  ('pyq-files', 'pyq-files', true, 20971520, array['application/pdf','image/jpeg','image/png','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','text/csv']),
  ('campus-events', 'campus-events', true, 20971520, array['application/json','image/jpeg','image/png','image/webp'])
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

-- Students may upload into the pending bucket; the object path must start
-- with the bucket folder. The row in pyq_papers is still created by the app
-- and only a moderator can move a file to the approved bucket.
drop policy if exists "pyq pending upload" on storage.objects;
create policy "pyq pending upload" on storage.objects
  for insert to anon, authenticated
  with check (
    bucket_id = 'pyq-pending'
    and (storage.foldername(name))[1] = 'pyq-pending'
  );

-- A uploader can read their own pending file.
drop policy if exists "pyq pending read own" on storage.objects;
create policy "pyq pending read own" on storage.objects
  for select to authenticated
  using (
    bucket_id = 'pyq-pending'
    and owner_id = auth.uid()::text
  );

-- Approved papers are public (the bucket itself is public, so the read
-- policy is only needed for the private bucket).
drop policy if exists "pyq approved read" on storage.objects;
create policy "pyq approved read" on storage.objects
  for select to public
  using (bucket_id = 'pyq');

-- The uploader may drop their own pending file when the queue row could not be
-- written (uploadPendingPaper() cleans up after a failed insert).
drop policy if exists "pyq pending delete own" on storage.objects;
create policy "pyq pending delete own" on storage.objects
  for delete to authenticated
  using (bucket_id = 'pyq-pending' and owner_id = auth.uid()::text);

-- ===========================================================================
-- Row level security
--
-- The project is deny-by-default: with row level security switched on and no
-- policy for a table, every read and write from the app is refused. The
-- offline-first screens hide that well - they quietly fall back to their
-- bundled data - so the failure used to look like "nothing to show" instead of
-- an error. These are the policies the shipped screens actually need, plus the
-- ones the worker's writes already relied on the service role for.
--
-- public.is_moderator() is SECURITY DEFINER on purpose. A policy that spells
-- out "exists (select 1 from public.moderators ...)" is itself filtered by the
-- moderator table's own row level security, so the check came back false and
-- the storage move was refused even for the owner. The helper reads the
-- allowlist directly, so it is the first thing to create.
-- ===========================================================================
create or replace function public.is_moderator()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.moderators m
    where lower(m.email) = lower(coalesce(auth.jwt() ->> 'email', ''))
  );
$$;
grant execute on function public.is_moderator() to anon, authenticated;

-- Owners only. Same SECURITY DEFINER reason as is_moderator(): a policy may
-- not read the allowlist directly.
create or replace function public.is_owner()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.moderators m
    where lower(m.email) = lower(coalesce(auth.jwt() ->> 'email', ''))
      and lower(m.role) = 'owner'
  );
$$;
grant execute on function public.is_owner() to authenticated;

-- Initial Admin Setup helper: true once the console has been claimed by a
-- real account. The owner runs supabase/seed.sql to claim it up front; if
-- they do not, the first person to sign in with a real Supabase Auth account
-- claims it.
create or replace function public.has_any_moderator()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.admin_claims);
$$;
grant execute on function public.has_any_moderator() to anon, authenticated;

create or replace function public.claim_initial_admin()
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  user_email text;
begin
  user_email := lower(coalesce(auth.jwt() ->> 'email', ''));
  if user_email = '' then
    return false;
  end if;

  if not exists (select 1 from public.admin_claims) then
    insert into public.admin_claims (email) values (user_email)
      on conflict (email) do nothing;
    insert into public.moderators (email, role) values (user_email, 'owner')
      on conflict (email) do update set role = 'owner';
    return true;
  end if;

  return false;
end;
$$;
grant execute on function public.claim_initial_admin() to authenticated;

-- Owners manage the allowlist from the app; nobody else can.
create or replace function public.set_moderator(target_email text, target_role text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  caller_email text := lower(coalesce(auth.jwt() ->> 'email', ''));
begin
  if not public.is_owner() then
    raise exception 'owner access required';
  end if;
  if target_email is null or target_email = '' then
    raise exception 'email required';
  end if;
  insert into public.moderators (email, role)
  values (lower(target_email), coalesce(nullif(target_role, ''), 'moderator'))
  on conflict (email) do update set role = excluded.role;
  return true;
end;
$$;
grant execute on function public.set_moderator(text, text) to authenticated;

create or replace function public.remove_moderator(target_email text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  caller_email text := lower(coalesce(auth.jwt() ->> 'email', ''));
begin
  if not public.is_owner() then
    raise exception 'owner access required';
  end if;
  delete from public.moderators where lower(email) = lower(target_email);
  return true;
end;
$$;
grant execute on function public.remove_moderator(text) to authenticated;

-- Download counter for an approved paper.
create or replace function public.increment_paper_downloads(paper_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.pyq_papers
     set downloads = downloads + 1
   where id = paper_id and status = 'approved';
end;
$$;
grant execute on function public.increment_paper_downloads(uuid) to anon, authenticated;

-- The allowlist itself: a signed-in user may read their own row (that is what
-- is_moderator() asks for), a moderator may read the whole list, and an owner
-- may change it.
alter table public.moderators enable row level security;
drop policy if exists "moderators read own" on public.moderators;
create policy "moderators read own" on public.moderators
  for select to authenticated
  using (lower(email) = lower(coalesce(auth.jwt() ->> 'email', '')) or public.is_moderator());

drop policy if exists "moderators owner write" on public.moderators;
create policy "moderators owner write" on public.moderators
  for all to authenticated
  using (public.is_owner())
  with check (public.is_owner());

alter table public.admin_claims enable row level security;
drop policy if exists "admin claims read own" on public.admin_claims;
create policy "admin claims read own" on public.admin_claims
  for select to authenticated
  using (lower(email) = lower(coalesce(auth.jwt() ->> 'email', '')) or public.is_moderator());

