-- The worker's own tables. These had NO row level security at all, so the
-- anon key could read every class's timetable snapshot, the push history and
-- the worker error log, and could write into them.
alter table public.timetable_snapshots enable row level security;
drop policy if exists "timetable snapshots read" on public.timetable_snapshots;
create policy "timetable snapshots read" on public.timetable_snapshots
  for select to anon, authenticated using (true);

alter table public.timetable_push_log enable row level security;
drop policy if exists "timetable push log read" on public.timetable_push_log;
create policy "timetable push log read" on public.timetable_push_log
  for select to authenticated using (public.is_moderator());

alter table public.worker_runs enable row level security;
drop policy if exists "worker runs read" on public.worker_runs;
create policy "worker runs read" on public.worker_runs
  for select to authenticated using (public.is_moderator());

alter table public.timetable_changes enable row level security;
drop policy if exists "timetable changes read" on public.timetable_changes;
create policy "timetable changes read" on public.timetable_changes
  for select to anon, authenticated using (true);

-- PYQ papers: the queue is private, the published shelf is public.
alter table public.pyq_papers enable row level security;

drop policy if exists "pyq papers approved read" on public.pyq_papers;
create policy "pyq papers approved read" on public.pyq_papers
  for select to anon, authenticated
  using (status = 'approved');

drop policy if exists "pyq papers moderator read" on public.pyq_papers;
create policy "pyq papers moderator read" on public.pyq_papers
  for select to authenticated
  using (public.is_moderator());

-- A signed-in student queues their own upload; it can only ever be pending,
-- and it may only ever be attributed to themselves. The old policy was
-- 'with check (status = 'pending')' alone, so any client could claim another
-- student's id and take their leaderboard points.
drop policy if exists "pyq papers insert pending" on public.pyq_papers;
create policy "pyq papers insert pending" on public.pyq_papers
  for insert to anon, authenticated
  with check (
    status = 'pending'
    and (uploader_id is null or uploader_id = auth.uid())
  );

-- Only a moderator changes a status (approve / reject / request changes).
drop policy if exists "pyq papers moderator update" on public.pyq_papers;
create policy "pyq papers moderator update" on public.pyq_papers
  for update to authenticated
  using (public.is_moderator())
  with check (public.is_moderator());

-- The moderation trail is written and read by moderators.
alter table public.pyq_moderation_log enable row level security;
drop policy if exists "pyq log moderator read" on public.pyq_moderation_log;
create policy "pyq log moderator read" on public.pyq_moderation_log
  for select to authenticated using (public.is_moderator());
drop policy if exists "pyq log moderator insert" on public.pyq_moderation_log;
create policy "pyq log moderator insert" on public.pyq_moderation_log
  for insert to authenticated with check (public.is_moderator());

-- Push tokens: a device owns its own rows. Guests have no user id, so the
-- anonymous token they register is allowed through with a null owner. The
-- policy has to name 'anon' explicitly or a guest's registration is refused
-- (guest mode is a hard requirement).
alter table public.device_tokens enable row level security;
drop policy if exists "device tokens own" on public.device_tokens;
create policy "device tokens own" on public.device_tokens
  for all to authenticated
  using (user_id is null or user_id = auth.uid())
  with check (user_id is null or user_id = auth.uid());

drop policy if exists "device tokens guest insert" on public.device_tokens;
create policy "device tokens guest insert" on public.device_tokens
  for insert to anon
  with check (user_id is null);

-- Reporting a paper: anyone signed in may report, only moderators may read
-- the whole queue, and a student may read their OWN reports (they used to
-- read nobody's, because there was no student read policy at all).
alter table public.reports enable row level security;
drop policy if exists "reports insert" on public.reports;
create policy "reports insert" on public.reports
  for insert to authenticated
  with check (reporter_id is null or reporter_id = auth.uid());

drop policy if exists "reports own read" on public.reports;
create policy "reports own read" on public.reports
  for select to authenticated
  using (
    reporter_id = auth.uid()
    or lower(reporter_email) = lower(coalesce(auth.jwt() ->> 'email', ''))
  );

drop policy if exists "reports moderator read" on public.reports;
create policy "reports moderator read" on public.reports
  for select to authenticated using (public.is_moderator());

drop policy if exists "reports moderator update" on public.reports;
create policy "reports moderator update" on public.reports
  for update to authenticated
  using (public.is_moderator())
  with check (public.is_moderator());

-- A student's own saved rows.
alter table public.profiles enable row level security;
drop policy if exists "profiles own" on public.profiles;
create policy "profiles own" on public.profiles
  for all to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

alter table public.notification_prefs enable row level security;
drop policy if exists "notification prefs own" on public.notification_prefs;
create policy "notification prefs own" on public.notification_prefs
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

alter table public.saved_notices enable row level security;
drop policy if exists "saved notices own" on public.saved_notices;
create policy "saved notices own" on public.saved_notices
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- Moderators move files between the buckets. The policy itself is created with
-- the rest of the row level security block at the end of this file, because it
-- calls public.is_moderator(), which has to exist first. A policy that spelled
-- the check out as a subquery on public.moderators could never match: the
-- subquery is filtered by that table's own row level security.
drop policy if exists "pyq moderator move" on storage.objects;
create policy "pyq moderator move" on storage.objects
  for all to authenticated
  using (bucket_id in ('pyq-pending','pyq') and public.is_moderator())
  with check (bucket_id in ('pyq-pending','pyq') and public.is_moderator());

-- Storage policies for campus-events (the CDN JSON the app reads) and for the
-- admin-uploaded documents. The write policies used to be open to 'anon', so
-- anybody could overwrite notices.json / events.json in the public bucket.
drop policy if exists "campus events storage read" on storage.objects;
create policy "campus events storage read" on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'campus-events');

drop policy if exists "campus events storage insert" on storage.objects;
create policy "campus events storage insert" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'campus-events' and public.is_moderator());

drop policy if exists "campus events storage update" on storage.objects;
create policy "campus events storage update" on storage.objects
  for update to authenticated
  using (bucket_id = 'campus-events' and public.is_moderator())
  with check (bucket_id = 'campus-events' and public.is_moderator());

drop policy if exists "campus events storage delete" on storage.objects;
create policy "campus events storage delete" on storage.objects
  for delete to authenticated
  using (bucket_id = 'campus-events' and public.is_moderator());

-- Documents uploaded by the admin console (date sheets, circulars).
drop policy if exists "pyq files read" on storage.objects;
create policy "pyq files read" on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'pyq-files');

drop policy if exists "pyq files moderator write" on storage.objects;
create policy "pyq files moderator write" on storage.objects
  for all to authenticated
  using (bucket_id = 'pyq-files' and public.is_moderator())
  with check (bucket_id = 'pyq-files' and public.is_moderator());

-- ===========================================================================
-- Realtime
--
-- The two broadcast channels (gbu_notices, gbu_version_updates) used to be
-- open to anybody. Any installed app could broadcast a fake official notice
-- into every other device's persistent cache, or force the compulsory-update
-- modal onto every phone with an APK URL of its choosing.
--
-- The channels are now PRIVATE: the client subscribes with
-- '{ config: { private: true } }', and only a moderator may read or send on
-- them. The policy body is guarded so a project without the realtime schema
-- still applies the rest of this script.
-- ===========================================================================
do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'realtime') then
    execute 'drop policy if exists "gbu notices read" on realtime.messages';
    execute 'create policy "gbu notices read" on realtime.messages for select to authenticated using (realtime.topic() = ''gbu_notices'' and public.is_moderator())';

    execute 'drop policy if exists "gbu notices send" on realtime.messages';
    execute 'create policy "gbu notices send" on realtime.messages for insert to authenticated with check (realtime.topic() = ''gbu_notices'' and public.is_moderator())';

    execute 'drop policy if exists "gbu version updates read" on realtime.messages';
    execute 'create policy "gbu version updates read" on realtime.messages for select to authenticated using (realtime.topic() = ''gbu_version_updates'' and public.is_moderator())';

    execute 'drop policy if exists "gbu version updates send" on realtime.messages';
    execute 'create policy "gbu version updates send" on realtime.messages for insert to authenticated with check (realtime.topic() = ''gbu_version_updates'' and public.is_moderator())';
  else
    raise notice 'realtime schema not present - skipping realtime policies';
  end if;
end;
$$;
